  if(b.dataset.cityConfirm){const c=cityById(b.dataset.cityConfirm),ids=currentSelection(c).map(m=>m.id);state.plan=[...new Set([...state.plan,...ids])];persist('guanwu-plan-v2',state.plan);GuanwuRoutePlanner.save(c,currentSelection(c),pace);toast(`已保存路线，并将 ${ids.length} 家馆加入“我的手记”。`)}
