  if(b.dataset.inquiryComplete){const id=b.dataset.inquiryComplete,text=document.querySelector('#inquiry-note').value.trim();if(!text){document.querySelector('#inquiry-note').focus();toast('先留下一句自己的发现，再收进手记。');return}saveRecord(id,{text,completedAt:new Date().toISOString()});render(false);toast('已收进“我的手记”中的观看练习。')}
